#include "stdlib/math/base/special/roundnf.h"
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <sys/time.h>

#define ITERATIONS 1000000

/**
* Runs benchmarks.
*
* @return elapsed time in seconds
*/
static double benchmark() {
	struct timeval start;
	struct timeval end;
	double elapsed;
	float x;
	float y;
	int i;

	gettimeofday( &start, NULL );
	for ( i = 0; i < ITERATIONS; i++ ) {
		x = ( ( (float)rand() / (float)RAND_MAX ) * 100.0f ) - 50.0f;
		y = stdlib_base_roundnf( x, -2 );
		if ( y != y ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	gettimeofday( &end, NULL );
	elapsed = (double)( end.tv_sec - start.tv_sec ) + ( (double)( end.tv_usec - start.tv_usec ) / 1.0e6 );
	if ( y != y ) {
		printf( "should not return NaN\n" );
	}
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	double rate;
	int i;

	// Warm-up:
	for ( i = 0; i < 1000; i++ ) {
		stdlib_base_roundnf( (float)i, -2 );
	}
	
	// Benchmark:
	printf( "Benchmark: roundnf\n" );
	elapsed = benchmark();
	rate = (double)ITERATIONS / elapsed;
	printf( "  iterations: %d\n", ITERATIONS );
	printf( "  elapsed: %f sec\n", elapsed );
	printf( "  rate: %f ops/sec\n", rate );
	
	return 0;
}
